const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: 'O' },
      { kind: 'text', payload: 'x' },
      { kind: 'text', payload: 'y' },
      { kind: 'text', payload: '-3' },
      { kind: 'text', payload: '2' },
      { kind: 'text', payload: 'P(-3,2)' },
      { kind: 'text', payload: '第二象限' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var margin = Math.max(24, Math.min(W, H) * 0.08);
    var unit = Math.min((W - 2 * margin) / 9, (H - 2 * margin) / 6);
    var ox = W * 0.58;
    var oy = H * 0.78;
    var px = ox - 3 * unit;
    var py = oy - 2 * unit;
    var color = '#26354a';

    function line(x1, y1, x2, y2) {
      return visualSdk.polyline([[x1, y1], [x2, y2]]);
    }

    function dashed(x1, y1, x2, y2, dash, gap) {
      var cmds = [];
      var dx = x2 - x1;
      var dy = y2 - y1;
      var len = Math.sqrt(dx * dx + dy * dy);
      if (len <= 0) return cmds;
      var ux = dx / len;
      var uy = dy / len;
      var t = 0;
      while (t < len) {
        var t2 = Math.min(t + dash, len);
        cmds.push(['M', x1 + ux * t, y1 + uy * t]);
        cmds.push(['L', x1 + ux * t2, y1 + uy * t2]);
        t += dash + gap;
      }
      return cmds;
    }

    function arrowHead(x, y, dx, dy, s) {
      var bx = x - dx * s;
      var by = y - dy * s;
      var nx = -dy;
      var ny = dx;
      var w = s * 0.42;
      return [
        ['M', x, y],
        ['L', bx + nx * w, by + ny * w],
        ['L', bx - nx * w, by - ny * w],
        ['Z']
      ];
    }

    var xAxis = line(margin, oy, W - margin, oy);
    var yAxis = line(ox, H - margin, ox, margin);
    var xArrow = arrowHead(W - margin, oy, 1, 0, 12);
    var yArrow = arrowHead(ox, margin, 0, -1, 12);
    var dashY = dashed(px, py, ox, py, 7, 5);
    var dashX = dashed(px, py, px, oy, 7, 5);
    var raY = visualSdk.polyline([[ox, py - 9], [ox - 9, py - 9], [ox - 9, py]]);
    var raX = visualSdk.polyline([[px, oy - 9], [px + 9, oy - 9], [px + 9, oy]]);
    var point = visualSdk.circle(px, py, 4.5);
    var originDot = visualSdk.circle(ox, oy, 2.2);

    return {
      schemaVersion: 1,
      sceneId: 'point-quadrant-source-transcription',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'xAxis', commands: xAxis },
        { id: 'yAxis', commands: yAxis },
        { id: 'xArrow', commands: xArrow },
        { id: 'yArrow', commands: yArrow },
        { id: 'dashY', commands: dashY },
        { id: 'dashX', commands: dashX },
        { id: 'raY', commands: raY },
        { id: 'raX', commands: raX },
        { id: 'point', commands: point },
        { id: 'originDot', commands: originDot }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'xAxis', fill: color, stroke: { width: 2 } },
          { type: 'path', pathId: 'yAxis', fill: color, stroke: { width: 2 } },
          { type: 'path', pathId: 'xArrow', fill: color, stroke: { width: 1 } },
          { type: 'path', pathId: 'yArrow', fill: color, stroke: { width: 1 } },
          { type: 'path', pathId: 'dashY', fill: color, stroke: { width: 1.6 } },
          { type: 'path', pathId: 'dashX', fill: color, stroke: { width: 1.6 } },
          { type: 'path', pathId: 'raY', fill: color, stroke: { width: 1.2 } },
          { type: 'path', pathId: 'raX', fill: color, stroke: { width: 1.2 } },
          { type: 'path', pathId: 'point', fill: color, stroke: { width: 1 } },
          { type: 'path', pathId: 'originDot', fill: color, stroke: { width: 1 } },
          { type: 'label', contentId: 'c0', anchor: { x: ox - 7, y: oy + 6 }, hAlign: 'right', vAlign: 'top', color: color },
          { type: 'label', contentId: 'c1', anchor: { x: W - margin + 4, y: oy + 14 }, hAlign: 'right', vAlign: 'top', color: color },
          { type: 'label', contentId: 'c2', anchor: { x: ox + 9, y: margin - 4 }, hAlign: 'left', vAlign: 'top', color: color },
          { type: 'label', contentId: 'c3', anchor: { x: px, y: oy + 8 }, hAlign: 'center', vAlign: 'top', color: color },
          { type: 'label', contentId: 'c4', anchor: { x: ox - 8, y: py }, hAlign: 'right', vAlign: 'middle', color: color },
          { type: 'label', contentId: 'c5', anchor: { x: px + 10, y: py - 8 }, hAlign: 'left', vAlign: 'bottom', color: color },
          { type: 'label', contentId: 'c6', anchor: { x: margin + 12, y: margin + 30 }, hAlign: 'left', vAlign: 'top', color: color }
        ]
      }
    };
  }
};
